<script>
  import { onMount } from 'svelte';
  import { page } from '$app/stores';
  import { goto, beforeNavigate } from '$app/navigation';
  import DashboardLayout from '$lib/components/layout/DashboardLayout.svelte';
  import Modal from '$lib/components/ui/Modal.svelte';
  import SearchableSelect from '$lib/components/ui/SearchableSelect.svelte';
  import DiscipleshipReview from '$lib/components/people/DiscipleshipReview.svelte';
  import GrowthPlan from '$lib/components/development/GrowthPlan.svelte';
  import ParticipationRadar from '$lib/components/development/ParticipationRadar.svelte';
  import * as peopleService from '$lib/services/peopleService.js';
  import { developmentEvidence, developmentPeriod, validDate } from '$lib/utils/developmentEvidence.js';
  import { todayDate } from '$lib/utils/reportingMetrics.js';
  import { session } from '$lib/auth/session.js';
  import { isDemoMode } from '$lib/convex.js';
  let people=$state([]), profiles=$state([]), directoryLoading=$state(true), summaryLoading=$state(false), error=$state(''), directoryError=$state('');
  let activeTab=$state('participation'), category=$state('prayer'), basis=$state('weeks'), periodOpen=$state(false), programsOpen=$state(false), programSearch=$state(''), dirtyPlan=$state(false), dirtyReview=$state(false), selectedMonth=$state('');
  let customFrom=$state(''), customTo=$state(''), customOpen=$state(false), rangeError=$state('');
  let request=0, permitNavigation=false;
  let discardOpen=$state(false), pendingUrl=$state(''), selectionVersion=$state(0);
  const demo=isDemoMode();
  const allowed=$derived(demo||Boolean($session.user?.canViewConfidential));
  const personId=$derived($page.url.searchParams.get('person')||'');
  const compareId=$derived($page.url.searchParams.get('compare')||'');
  const mode=$derived($page.url.searchParams.get('period')||($page.url.searchParams.has('from')?'custom':'three'));
  const range=$derived.by(()=>{const fallback=developmentPeriod(mode);return {from:$page.url.searchParams.get('from')||fallback.from,to:$page.url.searchParams.get('to')||fallback.to};});
  const validRange=$derived(validDate(range.from)&&validDate(range.to)&&range.from<=range.to&&range.to<=todayDate()&&Number(range.to.slice(0,4))-Number(range.from.slice(0,4))<10);
  const selectedPrograms=$derived($page.url.searchParams.has('programs')?($page.url.searchParams.get('programs')||'').split(',').filter(Boolean):null);
  const selected=$derived(profiles.find(p=>String(p.person._id||p.person.id)===personId));
  const comparison=$derived(profiles.find(p=>String(p.person._id||p.person.id)===compareId));
  const evidence=$derived(selected&&validRange?developmentEvidence(selected,range,selectedPrograms):null);
  const otherEvidence=$derived(comparison&&validRange?developmentEvidence(comparison,range,selectedPrograms):null);
  const name=p=>p?[p.first_name,p.last_name].filter(Boolean).join(' ').trim():'';
  const profileHref=p=>`/people/${encodeURIComponent(p.id||p._id)}`;
  const personOptions=$derived.by(()=>{
    const visible=people.filter(p=>p.member_status!=='archived');
    const counts=new Map();
    const key=p=>name(p).replace(/\s+/g,' ').toLocaleLowerCase();
    for(const p of visible)counts.set(key(p),(counts.get(key(p))||0)+1);
    return visible.map(p=>({value:String(p.id||p._id),label:`${name(p)} · ${p.member_status||'person'}${counts.get(key(p))>1&&p.phone?' · Phone ending '+p.phone.replace(/\D/g,'').slice(-4):''}`}));
  });
  const date=value=>new Date(`${value}T00:00:00`).toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});
  const programmes=$derived([...new Map([...(evidence?.programmes||[]),...(otherEvidence?.programmes||[])].map(p=>[p.id,p])).values()]);
  const periodLabels={three:'Last 3 complete months',six:'Last 6 complete months',month:'This month to date',custom:'Custom dates'};
  const metric=axis=>axis[basis].offered?`${axis[basis].attended} / ${axis[basis].offered} ${basis} · ${Math.round(axis[basis].attended/axis[basis].offered*100)}%`:'N/A · no known registers';
  const outreachMetrics=[{key:'collected',label:'Outreach contacts collected'},{key:'brought',label:'People brought · first Sunday visit'},{key:'returned',label:'Of those visitors, returned'}];
  const outreachMax=$derived(Math.max(1,...outreachMetrics.flatMap(m=>[evidence?.outreach[m.key]||0,otherEvidence?.outreach[m.key]||0])));
  async function navigate(values,replaceState=false){const url=new URL($page.url);for(const [key,value] of Object.entries(values)){value===null?url.searchParams.delete(key):url.searchParams.set(key,value);}await goto(url,{noScroll:true,keepFocus:true,replaceState});}
  function choosePerson(value){navigate({person:value||null,compare:value===compareId?null:compareId||null});}
  function choosePeriod(value){periodOpen=false;rangeError='';if(value==='custom'){customFrom=range.from;customTo=range.to;customOpen=true;return;}customOpen=false;const r=developmentPeriod(value);navigate({period:value,...r});}
  function applyRange(){if(!validDate(customFrom)||!validDate(customTo)||customFrom>customTo||customTo>todayDate()||Number(customTo.slice(0,4))-Number(customFrom.slice(0,4))>=10){rangeError='Choose valid dates up to today, within a ten-year range.';return;}rangeError='';customOpen=false;navigate({period:'custom',from:customFrom,to:customTo});}
  function toggleProgramme(id,checked){const set=new Set(selectedPrograms===null?programmes.map(p=>p.id):selectedPrograms);checked?set.add(id):set.delete(id);navigate({programs:[...set].join(',')},true);}
  function selectCategory(checked){const set=new Set(selectedPrograms===null?programmes.map(p=>p.id):selectedPrograms);for(const p of programmes.filter(p=>p.category===category)){checked?set.add(p.id):set.delete(p.id);}navigate({programs:[...set].join(',')},true);}
  async function loadDirectory(){directoryLoading=true;directoryError='';const result=await peopleService.getAll();if(result.error)directoryError='People could not be loaded. Please try again.';else people=result.data||[];directoryLoading=false;}
  async function loadSummary(ids=[personId,compareId].filter(Boolean)){
    const version=++request;
    if(!ids.length){profiles=[];error='';summaryLoading=false;return;}
    summaryLoading=true;error='';
    try{const result=await peopleService.getDevelopmentSummary([...new Set(ids)],range);if(version!==request)return;if(result.error)throw result.error;profiles=result.data||[];if(!profiles.length)throw new Error('Person not found or unavailable.');}
    catch(e){if(version===request){error=e.message||'Development could not be loaded.';}}
    finally{if(version===request)summaryLoading=false;}
  }
  $effect(()=>{const ids=[personId,compareId].filter(Boolean);range.from;range.to;if(validRange)loadSummary(ids);});
  $effect(()=>{ personId; compareId; range.from; range.to; selectedMonth=''; });
  onMount(loadDirectory);
  beforeNavigate(nav=>{
    const changingPerson=nav.to?.url.searchParams.get('person')!==personId||nav.to?.url.pathname!=='/development';
    if((dirtyPlan||dirtyReview)&&changingPerson&&!permitNavigation){
      nav.cancel();selectionVersion++;
      if(!nav.willUnload&&nav.to){pendingUrl=nav.to.url.href;discardOpen=true;}
    }
  });
  async function discardDraft(){discardOpen=false;permitNavigation=true;try{await goto(pendingUrl,{noScroll:true});}finally{permitNavigation=false;}}

  function dismiss(node){const click=e=>{if(!node.contains(e.target)||!e.target.closest('.picker')){periodOpen=false;programsOpen=false;}};const key=e=>{if(e.key==='Escape'){periodOpen=false;programsOpen=false;}};document.addEventListener('click',click);document.addEventListener('keydown',key);return{destroy(){document.removeEventListener('click',click);document.removeEventListener('keydown',key);}};}
</script>
<svelte:head><title>Development · Church Tracker</title></svelte:head>
<DashboardLayout>
<div class="development" use:dismiss>
  <header class="heading"><div><p class="eyebrow">Discipleship & development</p><h1>Participation & growth</h1><p>Understand participation, discuss progress and agree the next step.</p></div>{#if selected}<a class="profile-link" href={`/people/${personId}`}>View person profile →</a>{/if}</header>
  {#if demo}<p class="demo">Demo mode · sample people and records. Changes do not update church records.</p>{/if}
  {#key selectionVersion}<section class="toolbar" aria-label="Development selection">
    <SearchableSelect label="Person" options={personOptions} value={personId} onchange={({value})=>choosePerson(value)} disabled={directoryLoading} ariaLabel="Select person for Development" placeholder="Search a person…"/>
    <SearchableSelect label="Compare with" options={personOptions.filter(o=>o.value!==personId)} value={compareId} onchange={({value})=>navigate({compare:value||null})} disabled={directoryLoading||!personId} ariaLabel="Compare with another person" placeholder="Search a second person…"/>
    <div class="picker"><button class="picker-trigger" aria-expanded={periodOpen} onclick={()=>{periodOpen=!periodOpen;programsOpen=false;}}><span>{periodLabels[mode]||'Custom dates'}</span><span aria-hidden="true">⌄</span></button>{#if periodOpen}<div class="menu" aria-label="Reporting period">{#each Object.entries(periodLabels) as [value,label]}<button class:chosen={mode===value} onclick={()=>choosePeriod(value)}>{label}<span>{mode===value?'✓':''}</span></button>{/each}</div>{/if}</div>
  </section>{/key}
  {#if customOpen}<form class="custom-range" onsubmit={e=>{e.preventDefault();applyRange();}}><label>From<input type="date" bind:value={customFrom} max={todayDate()} required/></label><label>To<input type="date" bind:value={customTo} max={todayDate()} required/></label><button class="primary">Apply dates</button><button type="button" onclick={()=>customOpen=false}>Cancel</button>{#if rangeError}<p role="alert">{rangeError}</p>{/if}</form>{/if}
  {#if directoryError}<div class="error" role="alert">{directoryError}<button onclick={loadDirectory}>Retry people</button></div>{/if}
  {#if error}<div class="error" role="alert">{error}<button onclick={()=>loadSummary()}>Retry evidence</button></div>{/if}
  {#if !validRange}<div class="error" role="alert">The reporting dates are invalid. Choose a period above.</div>{/if}
  {#if directoryLoading}<div class="empty" role="status">Loading people…</div>{:else if !people.length&&!directoryError}<div class="empty"><h2>No people yet</h2><p>Add a person in the directory to start a development record.</p><a href="/people">Open People directory →</a></div>{:else if !personId}<div class="empty"><h2>Choose someone to begin</h2><p>Search the Person field above. Development is available for members, workers and emerging leaders.</p></div>{/if}
  {#if personId&&summaryLoading&&!selected}<div class="empty" role="status">Loading development…</div>{/if}
  {#if selected&&evidence}
    <div class="person-heading"><a class="avatar" href={profileHref(selected.person)} aria-label={`Open ${name(selected.person)}’s profile`}>{selected.person.first_name?.[0]}{selected.person.last_name?.[0]}</a><div><h2><a class="person-link" href={profileHref(selected.person)}>{name(selected.person)}</a></h2><p>{selected.person.member_status} {selected.person.role&&selected.person.role!=='no_role'?'· '+selected.person.role.replaceAll('_',' '):''}</p></div>{#if comparison}<span class="comparing">Compared with <a class="person-link" href={profileHref(comparison.person)}>{name(comparison.person)}</a></span>{/if}</div>
    <p class="period-note">{date(range.from)} – {date(range.to)} · Shared period and selected programmes{summaryLoading?' · Refreshing…':''}</p>
    <nav class="tabs" aria-label="Development view">{#each [['participation','Participation'],['review','Leader review'],['plan','Growth plan']] as [value,label]}<button aria-pressed={activeTab===value} onclick={()=>activeTab=value}>{label}</button>{/each}</nav>
    <div hidden={activeTab!=='participation'||Boolean(error)}>
      <section class="panel attendance"><div class="section-heading"><div><h2>Attendance pattern</h2><p>{basis==='weeks'?'Weeks with attendance ÷ weeks with selected gatherings':'Recorded attendance ÷ selected gatherings with known registers'}</p></div><div class="segmented" aria-label="Radar measure"><button aria-pressed={basis==='weeks'} onclick={()=>basis='weeks'}>Weeks</button><button aria-pressed={basis==='meetings'} onclick={()=>basis='meetings'}>Meetings</button></div></div>
      <div class="legend"><a class="person-link" href={profileHref(selected.person)}><i></i>{name(selected.person)}</a>{#if comparison}<a class="person-link" href={profileHref(comparison.person)}><i class="other"></i>{name(comparison.person)}</a>{/if}</div>
      <div class="radar-layout"><ParticipationRadar axes={evidence.axes} comparison={otherEvidence?.axes} {basis} selected={category} name={name(selected.person)} compareName={name(comparison?.person)}/><div class="axis-list">{#each evidence.axes as axis,i}<button class:active={category===axis.key} aria-pressed={category===axis.key} onclick={()=>category=axis.key}><span>{axis.label}</span><div><strong>{metric(axis)}</strong><small>{axis.meetings.attended} attended · {axis.weeks.attended} active week{axis.weeks.attended===1?'':'s'}</small>{#if otherEvidence}<small>{comparison.person.first_name}: {metric(otherEvidence.axes[i])}</small>{/if}{#if axis.unknown}<small>{axis.unknown} unconfirmed register{axis.unknown===1?'':'s'} excluded</small>{/if}</div></button>{/each}</div></div>
      <div class="breakdown"><div class="section-heading"><div><h3>{evidence.axes.find(a=>a.key===category)?.label} · by type</h3><p>Recorded registers in the selected programmes</p></div><div class="picker"><button class="picker-trigger" aria-expanded={programsOpen} onclick={()=>{programsOpen=!programsOpen;periodOpen=false;}}>Meeting types <span aria-hidden="true">⌄</span></button>{#if programsOpen}<div class="menu programmes"><input aria-label="Search meeting types" bind:value={programSearch} placeholder="Search meeting types…"/><div class="select-actions"><button onclick={()=>selectCategory(true)}>Select all</button><button onclick={()=>selectCategory(false)}>Clear all</button></div>{#each programmes.filter(p=>p.category===category&&p.label.toLowerCase().includes(programSearch.toLowerCase())) as programme}<label><input type="checkbox" checked={selectedPrograms===null||selectedPrograms.includes(programme.id)} onchange={e=>toggleProgramme(programme.id,e.target.checked)}/>{programme.label}</label>{/each}</div>{/if}</div></div>
      {#each evidence.breakdown.filter(p=>p.category===category) as programme}<div class="break-row"><span>{programme.label}</span><div><a class="person-link" href={profileHref(selected.person)}>{selected.person.first_name}</a>: {programme.meetings.attended} / {programme.meetings.offered} meetings<small>{programme.weeks.attended} weeks with attendance{programme.unknown?` · ${programme.unknown} registers unconfirmed`:''}</small>{#if otherEvidence}{@const other=otherEvidence.breakdown.find(p=>p.id===programme.id)}{#if other}<small><a class="person-link" href={profileHref(comparison.person)}>{comparison.person.first_name}</a>: {other.meetings.attended} / {other.meetings.offered} meetings · {other.weeks.attended} weeks</small>{/if}{/if}</div></div>{:else}<p class="empty-inline">No selected programmes with records in this period.</p>{/each}
      <p class="scope-note">This shows recorded participation in the selected programmes. Select the relevant bacenta or department; the chart does not imply every gathering was expected of this person.</p></div>
      </section>
      <div class="context-grid">
        <section class="panel"><h2>Monthly tithing</h2><p>At least one recorded tithe per calendar month</p>{#each [{data:evidence,person:selected.person},...(otherEvidence?[{data:otherEvidence,person:comparison.person}]:[])] as row}<div class="tithe-person"><h3><a class="person-link" href={profileHref(row.person)}>{row.person.first_name}</a>: {row.data.tithing.available?(row.data.tithing.eligible?`${row.data.tithing.recorded} / ${row.data.tithing.eligible} complete months`:'No complete eligible months'):'Confidential access required'}</h3>{#if row.data.tithing.available}<div class="months">{#each row.data.tithing.months as month}<button class:recorded={month.dates.length>0} class:partial={!month.complete} aria-label={`${row.person.first_name}, ${month.month}: ${month.dates.length?'tithe recorded':month.reason||'no tithe record'}`} onclick={()=>selectedMonth=`${row.person.first_name} · ${month.month}: ${month.dates.length?month.dates.map(date).join(', '):'No tithe record'}${month.reason?' · '+month.reason:''}`}><span>{new Date(`${month.month}-01T00:00:00`).toLocaleDateString('en-GB',{month:'short',...(range.from.slice(0,4)!==range.to.slice(0,4)?{year:'2-digit'}:{})})}</span><strong>{month.dates.length?'✓':month.complete?'—':'Open'}</strong></button>{/each}</div>{#if row.data.tithing.eligible&&row.data.tithing.recorded===row.data.tithing.eligible}<p class="small">Monthly giving recorded throughout the eligible period.</p>{/if}{/if}</div>{/each}<p class="small" aria-live="polite">{selectedMonth||'Select a month for its recorded dates. Partial months and months before recorded attendance history are excluded from consistency.'}</p><p class="small">The profile’s tither flag is not monthly evidence. No record means no recorded evidence of giving.</p></section>
        <section class="panel"><h2>Outreach & people brought</h2><p>Distinct people · one shared count scale</p>{#each outreachMetrics as item}<div class="outreach-metric"><h3>{item.label}</h3>{#each [{data:evidence,person:selected.person,other:false},...(otherEvidence?[{data:otherEvidence,person:comparison.person,other:true}]:[])] as row}<div class="bar-label"><a class="person-link" href={profileHref(row.person)}>{row.person.first_name}</a><strong>{row.data.outreach[item.key]}</strong></div><div class="bar-track"><div class:other={row.other} class="bar" style={`width:${row.data.outreach[item.key]/outreachMax*100}%`}></div></div>{/each}</div>{/each}{#if !evidence.outreach.complete}<p class="small">Only contacts in your permitted scope are counted. These are not church-wide totals.</p>{/if}<details class="explanation"><summary>How these counts work</summary><p>Contacts use an explicit collector link. People brought require their earliest recorded Sunday-service visit in this period, linked to their inviter. Returned visitors have a later service attendance in the period. Earlier unrecorded attendance cannot be established from these records.</p></details></section>
      </div>
    </div>
    {#key personId}<div hidden={activeTab!=='review'} class="review-panel"><DiscipleshipReview person={selected.person} bind:dirty={dirtyReview} onsave={()=>loadSummary()}/></div><div hidden={activeTab!=='plan'}><GrowthPlan {personId} {people} {allowed} agreements={selected.agreements} reviews={selected.agreementReviews} bind:dirty={dirtyPlan} onsave={()=>loadSummary()}/></div>{/key}
  {/if}
</div>
<Modal bind:isOpen={discardOpen} title="Leave this unsaved draft?" size="sm">
  <p class="text-sm text-muted-foreground">Your agreement or review has not been saved. Stay here to finish it, or discard it and continue.</p>
  {#snippet footer()}<button class="rounded-lg px-4 py-2 text-sm" onclick={()=>discardOpen=false}>Keep editing</button><button class="rounded-lg bg-destructive px-4 py-2 text-sm text-destructive-foreground" onclick={discardDraft}>Discard and continue</button>{/snippet}
</Modal>
</DashboardLayout>
<style>
 .person-link{text-decoration:underline;text-decoration-color:hsl(var(--muted-foreground)/.4);text-underline-offset:3px}.person-link:hover{color:hsl(var(--primary));text-decoration-color:currentColor}.person-link:focus-visible,.avatar:focus-visible{outline:2px solid hsl(var(--primary));outline-offset:4px;border-radius:3px}
 .development{max-width:1200px;margin:0 auto;padding-bottom:40px}.heading{display:flex;justify-content:space-between;align-items:center;gap:20px;margin-bottom:20px;flex-wrap:wrap}.eyebrow{font-size:12px;color:hsl(var(--muted-foreground));margin-bottom:5px}h1{font-size:28px;letter-spacing:-.7px;font-weight:600}h2{font-size:17px;font-weight:600}h3{font-size:14px;font-weight:500}p{font-size:13px;color:hsl(var(--muted-foreground));line-height:1.6;margin-top:5px}.profile-link{font-size:13px;color:hsl(var(--primary))}.demo{font-size:12px;color:hsl(var(--primary));margin:0 0 24px}.toolbar{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) auto;align-items:center;gap:18px;background:hsl(var(--card));border:1px solid hsl(var(--border));border-radius:12px;padding:24px 20px}.picker{position:relative;min-width:0}.picker-trigger{display:flex;justify-content:space-between;align-items:center;gap:20px;border:1px solid hsl(var(--border));border-radius:8px;background:hsl(var(--background));font-size:13px;padding:10px 13px;width:100%}.menu{position:absolute;right:0;top:calc(100% + 8px);width:250px;max-width:calc(100vw - 60px);background:hsl(var(--popover));border:1px solid hsl(var(--border));border-radius:10px;padding:6px;box-shadow:0 12px 28px #0003;z-index:40}.menu>button{display:flex;justify-content:space-between;width:100%;text-align:left;padding:10px;border-radius:6px;font-size:13px}.menu button:hover,.menu .chosen{background:hsl(var(--secondary));color:hsl(var(--primary))}.programmes>input{width:100%;padding:9px;border:1px solid hsl(var(--border));background:hsl(var(--background));border-radius:6px;font-size:13px}.programmes label{display:flex;align-items:center;gap:8px;padding:10px;font-size:13px}.programmes input[type=checkbox]{accent-color:hsl(var(--primary));width:16px;height:16px}.select-actions{display:flex;justify-content:space-between;padding:6px;font-size:12px;color:hsl(var(--primary))}.person-heading{display:flex;align-items:center;gap:12px;margin-top:26px}.avatar{width:42px;height:42px;display:grid;place-items:center;background:hsl(var(--primary)/.12);color:hsl(var(--primary));border-radius:50%;font-size:14px}.person-heading p{font-size:12px;text-transform:capitalize}.comparing{margin-left:auto;font-size:12px;color:hsl(var(--muted-foreground))}.period-note{font-size:12px;margin:16px 0}.tabs{display:flex;gap:24px;border-bottom:1px solid hsl(var(--border));margin-bottom:22px}.tabs button{padding:10px 0;font-size:13px;color:hsl(var(--muted-foreground));border-bottom:2px solid transparent}.tabs button[aria-pressed=true]{border-color:hsl(var(--primary));color:hsl(var(--foreground))}.panel{padding:24px;border:1px solid hsl(var(--border));border-radius:14px;background:hsl(var(--card));min-width:0}.section-heading{display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.segmented{display:flex;gap:4px}.segmented button{padding:7px 12px;border:1px solid hsl(var(--border));border-radius:7px;font-size:12px}.segmented button[aria-pressed=true]{color:hsl(var(--primary));background:hsl(var(--primary)/.1);border-color:hsl(var(--primary)/.5)}.legend{display:flex;flex-wrap:wrap;gap:20px;font-size:12px;margin:20px 0 4px}.legend i{display:inline-block;width:18px;border-top:2px solid hsl(var(--primary));margin-right:7px;vertical-align:middle}.legend i.other{border-color:hsl(var(--warning));border-top-style:dashed}.radar-layout{display:grid;grid-template-columns:1fr 1.15fr;gap:24px;align-items:center;margin:12px 0 24px}.axis-list{display:grid;gap:5px}.axis-list button{display:flex;align-items:center;justify-content:space-between;gap:16px;width:100%;padding:14px 10px;text-align:left;border-radius:8px;font-size:13px}.axis-list .active{background:hsl(var(--primary)/.09)}.axis-list strong{font-size:13px;font-weight:500}.axis-list small,.break-row small{display:block;font-size:12px;color:hsl(var(--muted-foreground));margin-top:3px}.breakdown{border-top:1px solid hsl(var(--border));padding-top:20px}.break-row{displ